// @ts-check
"use strict";

/**
 * Safe NTQQ `nt_data` Cache Watermark Scanner & Allowlisted Pruner (`src/core/nt_cache_pruner.js`)
 *
 * Inspects and prunes expired transient cache files generated by official Linux QQ NT
 * under `<qqConfigRoot>/nt_qq_<hash>/nt_data/{Pic,Emoji,Video,Ptt,log,log-cache}`.
 *
 * Safety invariants:
 * - Strictly allowlists ONLY transient media/log cache subdirectories (`Pic`, `Emoji`,
 *   `Video`, `Ptt`, `log`, `log-cache`).
 * - NEVER enters or touches `db`, `mmkv`, `msf`, `UnitedConfig`, `File` (user-received
 *   documents), `avatar`, `global`, `auth`, `Partitions`, or `Local Storage`.
 * - NEVER follows symbolic links (`lstat` only) and NEVER deletes database/state files
 *   (`.db`, `.sqlite`, `.wal`, `.shm`, `.ldb`, `.lock`, `.json`).
 * - Bounded entry traversal (`maxEntries`) prevents unbounded I/O stalls on huge volumes.
 */

const fs = require("fs");
const os = require("os");
const path = require("path");

const SAFE_NT_DATA_CATEGORIES = Object.freeze([
  "Pic",
  "Emoji",
  "Video",
  "Ptt",
  "log",
  "log-cache",
]);

const PROTECTED_EXTENSIONS = new Set([
  ".db",
  ".sqlite",
  ".sqlite3",
  ".wal",
  ".shm",
  ".ldb",
  ".lock",
  ".json",
  ".pem",
  ".key",
]);

const DEFAULT_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
const DEFAULT_MAX_ENTRIES = 50000;

/**
 * @typedef {object} NtCacheCategoryStat
 * @property {number} files
 * @property {number} bytes
 */

/**
 * @typedef {object} NtCacheUsageReport
 * @property {string[]} roots
 * @property {number} totalFiles
 * @property {number} totalBytes
 * @property {boolean} truncated
 * @property {Record<string, NtCacheCategoryStat>} byCategory
 */

/**
 * @typedef {object} NtCachePruneReport
 * @property {string[]} roots
 * @property {number} scannedFiles
 * @property {number} deletedFiles
 * @property {number} freedBytes
 * @property {number} remainingFiles
 * @property {number} remainingBytes
 * @property {number} removedEmptyDirs
 * @property {number} errors
 * @property {boolean} truncated
 */

/**
 * Discovers candidate `<qqConfigRoot>` directories containing `nt_qq_*` profiles.
 * Auto-discovery of container/OS home roots is gated on explicit `ntCacheDir` or
 * live Electron runtime (`allowSystemDiscovery`) so developer unit tests never
 * accidentally touch a developer's personal desktop QQ installation.
 *
 * @param {{ ntCacheDir?: string, allowSystemDiscovery?: boolean }} [options={}]
 * @returns {string[]}
 */
function resolveNtCacheRoots(options = {}) {
  /** @type {string[]} */
  const candidates = [];
  const explicitDir = typeof options.ntCacheDir === "string" ? options.ntCacheDir.trim() : "";
  if (explicitDir) {
    candidates.push(path.resolve(explicitDir));
  } else if (options.allowSystemDiscovery) {
    candidates.push("/app/.config/QQ");
    try {
      const home = os.homedir();
      if (home) {
        candidates.push(path.join(home, ".config", "QQ"));
      }
    } catch (_homeErr) {
      // Ignore missing homedir in restricted container namespaces.
    }
  }

  /** @type {Set<string>} */
  const seen = new Set();
  /** @type {string[]} */
  const validRoots = [];
  for (const dir of candidates) {
    const norm = path.resolve(dir);
    if (seen.has(norm)) continue;
    seen.add(norm);
    try {
      const st = fs.lstatSync(norm);
      if (st.isDirectory() && !st.isSymbolicLink()) {
        validRoots.push(norm);
      }
    } catch (_statErr) {
      // Candidate directory does not exist.
    }
  }
  return validRoots;
}

/**
 * Enumerates allowlisted `<root>/nt_qq_<hash>/nt_data/<category>` directories.
 * Also supports passing an `nt_qq_<hash>` or `nt_data` directory directly as `ntCacheDir`.
 *
 * @param {string[]} roots
 * @param {readonly string[]} [categories=SAFE_NT_DATA_CATEGORIES]
 * @returns {Array<{ root: string, category: string, dirPath: string }>}
 */
function discoverAllowlistedCategoryDirs(roots, categories = SAFE_NT_DATA_CATEGORIES) {
  /** @type {Set<string>} */
  const allowedSet = new Set(categories.filter((c) => SAFE_NT_DATA_CATEGORIES.includes(c)));
  /** @type {Array<{ root: string, category: string, dirPath: string }>} */
  const targets = [];
  /** @type {Set<string>} */
  const seenDirs = new Set();

  /**
   * @param {string} root
   * @param {string} ntDataDir
   */
  const collectFromNtData = (root, ntDataDir) => {
    try {
      const st = fs.lstatSync(ntDataDir);
      if (!st.isDirectory() || st.isSymbolicLink()) return;
    } catch (_err) {
      return;
    }
    for (const cat of allowedSet) {
      const catDir = path.join(ntDataDir, cat);
      const normCat = path.resolve(catDir);
      if (seenDirs.has(normCat)) continue;
      try {
        const cst = fs.lstatSync(normCat);
        if (cst.isDirectory() && !cst.isSymbolicLink()) {
          seenDirs.add(normCat);
          targets.push({ root, category: cat, dirPath: normCat });
        }
      } catch (_catErr) {
        // Category subdirectory absent in this profile.
      }
    }
  };

  for (const root of roots) {
    const base = path.basename(root);
    if (base === "nt_data") {
      collectFromNtData(root, root);
      continue;
    }
    if (base.startsWith("nt_qq_")) {
      collectFromNtData(root, path.join(root, "nt_data"));
      continue;
    }
    collectFromNtData(root, path.join(root, "nt_data"));
    try {
      const entries = fs.readdirSync(root, { withFileTypes: true });
      for (const ent of entries) {
        if (ent.isDirectory() && !ent.isSymbolicLink() && ent.name.startsWith("nt_qq_")) {
          collectFromNtData(root, path.join(root, ent.name, "nt_data"));
        }
      }
    } catch (_readErr) {
      // Ignore unreadable root directory.
    }
  }

  return targets;
}

/**
 * @param {string} fileName
 * @returns {boolean}
 */
function isProtectedCacheFileName(fileName) {
  const ext = path.extname(fileName).toLowerCase();
  if (PROTECTED_EXTENSIONS.has(ext)) return true;
  const lower = fileName.toLowerCase();
  return lower.endsWith("-wal") || lower.endsWith("-shm") || lower.endsWith("-journal");
}

/**
 * Scans allowlisted `nt_data` cache usage without modifying any files.
 *
 * @param {{
 *   ntCacheDir?: string,
 *   allowSystemDiscovery?: boolean,
 *   categories?: string[],
 *   maxEntries?: number
 * }} [options={}]
 * @returns {Promise<NtCacheUsageReport>}
 */
async function inspectNtCacheUsage(options = {}) {
  const roots = resolveNtCacheRoots(options);
  const maxEntries =
    Number.isFinite(Number(options.maxEntries)) && Number(options.maxEntries) > 0
      ? Math.floor(Number(options.maxEntries))
      : DEFAULT_MAX_ENTRIES;
  const catTargets = discoverAllowlistedCategoryDirs(roots, options.categories);

  /** @type {Record<string, NtCacheCategoryStat>} */
  const byCategory = {};
  for (const cat of SAFE_NT_DATA_CATEGORIES) {
    byCategory[cat] = { files: 0, bytes: 0 };
  }

  let totalFiles = 0;
  let totalBytes = 0;
  let visited = 0;
  let truncated = false;

  for (const target of catTargets) {
    /** @type {string[]} */
    const stack = [target.dirPath];
    while (stack.length > 0) {
      if (visited >= maxEntries) {
        truncated = true;
        break;
      }
      const curDir = /** @type {string} */ (stack.pop());
      /** @type {fs.Dirent[]} */
      let entries;
      try {
        entries = await fs.promises.readdir(curDir, { withFileTypes: true });
      } catch (_dirErr) {
        continue;
      }
      for (const ent of entries) {
        if (visited >= maxEntries) {
          truncated = true;
          break;
        }
        visited += 1;
        if (ent.isSymbolicLink()) continue;
        const fullPath = path.join(curDir, ent.name);
        if (ent.isDirectory()) {
          stack.push(fullPath);
        } else if (ent.isFile() && !isProtectedCacheFileName(ent.name)) {
          try {
            const st = await fs.promises.lstat(fullPath);
            if (!st.isSymbolicLink() && st.isFile()) {
              totalFiles += 1;
              totalBytes += st.size;
              byCategory[target.category].files += 1;
              byCategory[target.category].bytes += st.size;
            }
          } catch (_statErr) {
            // File concurrently removed by QQ.
          }
        }
      }
    }
    if (truncated) break;
  }

  return {
    roots,
    totalFiles,
    totalBytes,
    truncated,
    byCategory,
  };
}

/**
 * Prunes regular files inside allowlisted `nt_data` cache subdirectories whose `mtimeMs`
 * is strictly older than `now - maxAgeMs`, leaving recent active media and all database /
 * credential / user-document directories untouched.
 *
 * @param {{
 *   ntCacheDir?: string,
 *   allowSystemDiscovery?: boolean,
 *   maxAgeMs?: number,
 *   categories?: string[],
 *   maxEntries?: number,
 *   now?: number
 * }} [options={}]
 * @returns {Promise<NtCachePruneReport>}
 */
async function pruneNtCache(options = {}) {
  const roots = resolveNtCacheRoots(options);
  const rawMaxAge = Number(options.maxAgeMs);
  const maxAgeMs =
    Number.isFinite(rawMaxAge) && rawMaxAge >= 0 ? Math.floor(rawMaxAge) : DEFAULT_MAX_AGE_MS;
  const maxEntries =
    Number.isFinite(Number(options.maxEntries)) && Number(options.maxEntries) > 0
      ? Math.floor(Number(options.maxEntries))
      : DEFAULT_MAX_ENTRIES;
  const now = Number.isFinite(Number(options.now)) ? Number(options.now) : Date.now();
  const cutoffMs = now - maxAgeMs;
  const catTargets = discoverAllowlistedCategoryDirs(roots, options.categories);

  let scannedFiles = 0;
  let deletedFiles = 0;
  let freedBytes = 0;
  let remainingFiles = 0;
  let remainingBytes = 0;
  let removedEmptyDirs = 0;
  let errors = 0;
  let visited = 0;
  let truncated = false;

  for (const target of catTargets) {
    /** @type {string[]} */
    const stack = [target.dirPath];
    /** @type {string[]} */
    const visitedSubdirs = [];

    while (stack.length > 0) {
      if (visited >= maxEntries) {
        truncated = true;
        break;
      }
      const curDir = /** @type {string} */ (stack.pop());
      if (curDir !== target.dirPath) {
        visitedSubdirs.push(curDir);
      }
      /** @type {fs.Dirent[]} */
      let entries;
      try {
        entries = await fs.promises.readdir(curDir, { withFileTypes: true });
      } catch (_readErr) {
        errors += 1;
        continue;
      }

      for (const ent of entries) {
        if (visited >= maxEntries) {
          truncated = true;
          break;
        }
        visited += 1;
        if (ent.isSymbolicLink()) continue;
        const fullPath = path.join(curDir, ent.name);
        if (ent.isDirectory()) {
          stack.push(fullPath);
          continue;
        }
        if (!ent.isFile() || isProtectedCacheFileName(ent.name)) {
          continue;
        }
        try {
          const st = await fs.promises.lstat(fullPath);
          if (st.isSymbolicLink() || !st.isFile()) continue;
          scannedFiles += 1;
          if (st.mtimeMs <= cutoffMs) {
            await fs.promises.unlink(fullPath);
            deletedFiles += 1;
            freedBytes += st.size;
          } else {
            remainingFiles += 1;
            remainingBytes += st.size;
          }
        } catch (_unlinkErr) {
          errors += 1;
        }
      }
    }

    // Best-effort bottom-up removal of empty date-partition leaf directories (never top category dir)
    for (let i = visitedSubdirs.length - 1; i >= 0; i -= 1) {
      try {
        await fs.promises.rmdir(visitedSubdirs[i]);
        removedEmptyDirs += 1;
      } catch (_rmdirErr) {
        // Non-empty directory; keep intact.
      }
    }

    if (truncated) break;
  }

  return {
    roots,
    scannedFiles,
    deletedFiles,
    freedBytes,
    remainingFiles,
    remainingBytes,
    removedEmptyDirs,
    errors,
    truncated,
  };
}

module.exports = {
  SAFE_NT_DATA_CATEGORIES,
  DEFAULT_MAX_AGE_MS,
  resolveNtCacheRoots,
  discoverAllowlistedCategoryDirs,
  isProtectedCacheFileName,
  inspectNtCacheUsage,
  pruneNtCache,
};
